#!/usr/bin/env bash
# Вход в сессию: канон печатается сам. Правило, которое надо вспоминать,
# не работает — работает то, которое печатается.
set -u
HOME_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
REPO="$(cd "$HOME_DIR/../.." && pwd)"

echo "=============================================================="
echo " Librarer — дом исполнителя в refedoc. Роль: ПОГРАНИЧНИК."
echo " refedoc — ПУБЛИЧНАЯ зона. Источники — приватная."
echo "--------------------------------------------------------------"
echo " 1. Стенограммы переписки сюда НЕ кладутся: ни chatlog/, ни"
echo "    sessions/, ни context-export/, ни *.jsonl, ни пересказ."
echo "    Отчёт по чатлогу — в приватный репозиторий-источник."
echo " 2. Секреты и ключи — тем более. Опубликованное не"
echo "    разопубликовать: удаление оставляет их в истории."
echo " 3. Производное (INVENTORY.md, index.json, указатели) собирается"
echo "    прогоном и руками не правится."
echo " 4. Не плодить ветки: работа в main. Ветка — только если без неё"
echo "    нельзя, и живёт до слияния. Неслитая ветка не работа, а её вид."
echo "--------------------------------------------------------------"
echo " Канон целиком : env/Librarer/RULES.md"
echo " Досмотр вручную: python3 env/Librarer/hooks/guard.py staged"
echo " Поставить крючки: bash env/Librarer/hooks/install.sh"
echo "=============================================================="

if [ ! -x "$REPO/.git/hooks/pre-commit" ]; then
  echo " ВНИМАНИЕ: git-крючок pre-commit не поставлен — граница держится"
  echo " только на дисциплине. Поставьте: bash env/Librarer/hooks/install.sh"
fi
